import { useNavigate } from "react-router-dom";

function Navbar() {
  const navigate = useNavigate();

  const logout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <nav className="navbar px-4 py-2 d-flex justify-content-between">
      <h5 className="mb-0">🗳 Online Voting System</h5>

      <button className="btn btn-danger btn-sm" onClick={logout}>
        Logout
      </button>
    </nav>
  );
}

export default Navbar;
